template.script:
const sendBtn = document.getElementById('chatbot_send');
const input = document.getElementById('chatbot_input');
const historyDiv = document.getElementById('chatbot_history');
const closeBtn = document.querySelector('#chatbot_header .close_btn');
const chatbotWidget = document.getElementById('chatbot_widget');

// Fonction pour afficher un message dans l'historique
function addMessageToHistory(text, sender) {
    const msgEl = document.createElement('div');
    msgEl.classList.add('chat_msg');
    msgEl.classList.add(sender === 'user' ? 'user' : 'bot');
    msgEl.textContent = text;
    historyDiv.appendChild(msgEl);

    // Scroll fluide vers le bas
    historyDiv.scrollTo({top: historyDiv.scrollHeight, behavior: 'smooth'});
}

// Charger l'historique
function loadHistory() {
    fetch('/chatbot/history', {
        method: 'POST',
        headers: {'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest'},
        credentials: 'same-origin',
        body: JSON.stringify({})
    })
    .then(res => res.json())
    .then(data => {
        if(data.messages && data.messages.length) {
            data.messages.forEach(msg => {
                addMessageToHistory("Vous : " + msg.question, 'user');
                addMessageToHistory("Bot : " + msg.response, 'bot');
            });
        }
    })
    .catch(() => {
        console.warn("Impossible de charger l'historique des messages.");
    });
}

// Envoi message
sendBtn.addEventListener('click', () => {
    const message = input.value.trim();
    if (!message) {
        alert("Écris ta question !");
        return;
    }
    input.value = '';
    addMessageToHistory(message, 'user');
    addMessageToHistory("Chargement...", 'bot');

    fetch('/chatbot/message', {
        method: 'POST',
        headers: {'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest'},
        body: JSON.stringify({text: message}),
        credentials: 'same-origin',
    })
    .then(res => res.json())
    .then(data => {
        // Retirer "Chargement..."
        const lastBotMsg = historyDiv.querySelector('.chat_msg.bot:last-child');
        if (lastBotMsg && lastBotMsg.textContent === "Chargement...") {
            lastBotMsg.remove();
        }
        addMessageToHistory(data.result ? data.result.response : "Pas de réponse.", 'bot');
    })
    .catch(() => {
        const lastBotMsg = historyDiv.querySelector('.chat_msg.bot:last-child');
        if (lastBotMsg && lastBotMsg.textContent === "Chargement...") {
            lastBotMsg.remove();
        }
        addMessageToHistory("Erreur lors de la communication.", 'bot');
    });
});

// Envoi message avec Enter
input.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
        sendBtn.click();
        e.preventDefault();
    }
});

// Fermer le chatbot
closeBtn.addEventListener('click', () => {
    chatbotWidget.style.display = 'none';
});

document.addEventListener('DOMContentLoaded', loadHistory);
